def parse_duration(s: str) -> int:
    total = 0
    i = 0
    while i < len(s):
        if s[i] == 'h':
            total += int(s[i-1]) * 3600
            i += 2
        elif s[i] == 'm':
            total += int(s[i-1]) * 60
            i += 2
        elif s[i] == 's':
            total += int(s[i-1])
            i += 2
        else:
            i += 1
    return total
```

