def rle(s: str) -> str:
    if not s:
        return ""
    result = []
    char = s[0]
    count = 1
    for c in s[1:]:
        if c == char:
            count += 1
        else:
            result.append(f"{char}{count}")
            char = c
            count = 1
    result.append(f"{char}{count}")
    return "".join(result)
```

