def is_balanced(s: str) -> bool:
    stack = []
    brackets = {'(': ')', '[': ']', '{': '}'}
    for char in s:
        if char in brackets:
            stack.append(char)
        elif len(stack) > 0 and stack[-1] == brackets[char]:
            stack.pop()
        else:
            return False
    return len(stack) == 0
```

