def parse_csv_line(line: str) -> list[str]:
    fields = []
    i = 0
    while i < len(line):
        if line[i] == '"':
            i += 1
            while i < len(line) and line[i] != '"':
                if line[i] == ',':
                    fields.append(line[i-1:i])
                    i += 1
                    break
                i += 1
            if i < len(line) and line[i] == '"':
                i += 1
        else:
            fields.append(line[i])
            i += 1
    return fields
```

