def luhn_valid(number: str) -> bool:
    total = 0
    for i in range(len(number) - 1, -1, -1):
        digit = int(number[i])
        if i % 2 == 1:
            digit = digit * 2
        total += digit
        if digit > 9:
            total += digit - 9
    return total % 10 == 0
```

