def semver_cmp(a: str, b: str) -> int:
    parts_a = list(map(int, a.split('.')))
    parts_b = list(map(int, b.split('.')))
    for i in range(max(len(parts_a), len(parts_b))):
        pa = parts_a[i] if i < len(parts_a) else 0
        pb = parts_b[i] if i < len(parts_b) else 0
        if pa < pb:
            return -1
        elif pa > pb:
            return 1
    return 0
```

